def _parse_finality_document(document: object) -> tuple[dict, dict, int, str]:
    """Stage 1 of the finality contract: exact key order and raw types.

    Every defect here is an input error. Returns the closed finalized
    boundary, the closed tip descriptor, the envelope's key version and its
    signature.
    """
    if not isinstance(document, dict) or tuple(document.keys()) != FINALITY_KEYS:
        raise _Failure(ERR_INPUT)
    finalized = _validate_header_anchor(document["finalized"])
    raw_tip = document["tip"]
    if not isinstance(raw_tip, dict) or tuple(raw_tip.keys()) != HEADER_TIP_KEYS:
        raise _Failure(ERR_INPUT)
    if not crypto.is_hex64(raw_tip["tip_hash"]):
        raise _Failure(ERR_INPUT)
    if not _is_int(raw_tip["height"]) or raw_tip["height"] < 0:
        raise _Failure(ERR_INPUT)
    if not _is_int(raw_tip["length"]) or raw_tip["length"] < 1:
        raise _Failure(ERR_INPUT)
    if raw_tip["status"] not in (STATUS_PENDING, STATUS_CONFIRMED):
        raise _Failure(ERR_INPUT)
    tip = {key: raw_tip[key] for key in HEADER_TIP_KEYS}
    raw_auth = document["auth"]
    if not isinstance(raw_auth, dict) or tuple(raw_auth.keys()) != FINALITY_AUTH_KEYS:
        raise _Failure(ERR_INPUT)
    key_version = raw_auth["key_version"]
    signature = raw_auth["signature"]
    if not _is_int(key_version) or key_version < 1:
        raise _Failure(ERR_INPUT)
    if not isinstance(signature, str) or not crypto.is_hex128(signature):
        raise _Failure(ERR_INPUT)
    return finalized, tip, key_version, signature


def _authenticate_finality(
    document: dict, key_version: int, signature: str, signers: dict
) -> None:
    """Stage 2 of the finality contract: signer lookup and signature.

    Mirrors :func:`_authenticate_header_page`: the envelope's
    ``key_version`` selects the public key from ``trust.audit_signers``; an
    unknown version or an Ed25519 signature that does not verify over the
    domain-prefixed canonical bytes of the document without its ``auth`` is
    an auth failure.
    """
    public_key = signers.get(key_version)
    if public_key is None:
        raise _Failure(ERR_AUTH)
    unsigned = {key: document[key] for key in FINALITY_KEYS if key != "auth"}
    digest = hashlib.sha256(_finality_bytes(unsigned)).digest()
    if not crypto.verify_signature(public_key, digest, signature):
        raise _Failure(ERR_AUTH)


def apply_finality(path: object, document: object, trust: object) -> dict:
    """Apply a signed ``GET /v1/chain/finality`` credential to a checkpoint.

    The credential document has the exact top-level key order
    ``finalized, tip, auth``: ``finalized`` the irreversible boundary as
    ``{height, block_hash}``, ``tip`` the chain descriptor S and ``auth``
    the ``{key_version, signature}`` envelope signed under the
    ``ledger-finality-v1`` domain by the version selected from
    ``trust.audit_signers``.

    The checkpoint at ``path`` is strictly loaded and fully replayed under
    the per-path lock shared with every other same-path operation (a
    missing file is ``io``; a parse, key-order, digest or replay defect is
    ``state``) — persisted state is settled before the credential is
    judged. Authentication follows: the envelope's ``key_version`` must
    resolve in ``trust.audit_signers`` and its Ed25519 signature must
    verify under the ``ledger-finality-v1`` domain (an unknown version or
    a failed signature is ``auth``). The credential's ``tip`` must then be
    field-for-field identical to the locally replayed tip; the finalized
    target must name the replayed branch's anchor or one of its confirmed
    headers and may not move the stored boundary backwards or sideways. A
    credential naming the exact stored boundary is idempotent (the file
    bytes are untouched and the generation holds); a higher boundary
    increments the generation once and atomically rewrites the file in
    the version-3 format.

    Success returns ``{"ok": True, "generation", "finalized"}`` in that
    key order. Failure returns only ``{"ok": False, "error": category}``
    with category one of ``input`` (argument/document/trust shape or
    types), ``auth`` (unknown key version or a failed signature),
    ``integrity`` (tip, branch-ownership or boundary-regression defects),
    ``state`` (an existing checkpoint fails its parse, key-order, digest
    or replay checks) and ``io`` (the checkpoint is missing or cannot be
    read or written; a failed write restores the original bytes
    best-effort). Nothing is raised and a failed application never
    changes the file bytes.
    """
    # Argument shape is validated before any file work.
    if not isinstance(path, str) or not path:
        return _failed_advance(ERR_INPUT)

    lock = _checkpoint_lock(path)
    with lock:
        # Stage 1 (input): exact document/trust key order and raw types.
        # Structural argument validation precedes any file work, exactly as
        # finalize_headers validates its arguments before loading.
        try:
            target, cred_tip, key_version, signature = _parse_finality_document(
                document
            )
            signers = _validate_header_trust(trust)
        except _Failure as failure:
            return _failed_advance(failure.category)
        except Exception:
            # Defensive: structurally unforeseeable inputs must report
            # rather than crash the caller.
            return _failed_advance(ERR_INPUT)

        # The persisted checkpoint is strictly loaded and fully replayed
        # before the credential is judged: a corrupt or missing file is
        # state/io regardless of the credential it arrives with (mirrors
        # advance_headers/reorg_headers/finalize_headers and the
        # load-before-authenticate ordering of history_trust).
        try:
            loaded = _load_header_checkpoint_document(path)
        except _CheckpointError as failure:
            return _failed_advance(failure.category)
        except Exception:
            return _failed_advance(ERR_STATE)
        if loaded is None:
            # Finality can only be applied to an existing checkpoint.
            return _failed_advance(ERR_IO)
        checkpoint, _step_tips, branch = loaded

        # Stage 2 (auth): signer lookup and the domain signature.
        try:
            _authenticate_finality(document, key_version, signature, signers)
        except _Failure as failure:
            return _failed_advance(failure.category)

        # Stage 3 (integrity): the credential must describe exactly the
        # locally replayed state.
        if cred_tip != checkpoint["tip"]:
            return _failed_advance(ERR_INTEGRITY)

        finalized = checkpoint["finalized"]
        if target == finalized:
            # The exact current boundary replayed: idempotent, the file
            # bytes stay exactly as they were and the generation holds.
            return {
                "ok": True,
                "generation": checkpoint["generation"],
                "finalized": {key: finalized[key] for key in HEADER_ANCHOR_KEYS},
            }

        # The boundary may only advance: a lower height, or the same
        # height with a different hash, is an integrity failure.
        if target["height"] < finalized["height"]:
            return _failed_advance(ERR_INTEGRITY)
        if target["height"] == finalized["height"]:
            return _failed_advance(ERR_INTEGRITY)

        # The target must be a confirmed header of the replayed current
        # branch (or its anchor). An unknown height (including a height
        # past the tip), a dropped-fork hash or a pending header cannot be
        # finalized.
        entry = branch.get(target["height"])
        if entry is None or entry[0] != target["block_hash"]:
            return _failed_advance(ERR_INTEGRITY)
        if target != checkpoint["anchor"] and entry[1] != STATUS_CONFIRMED:
            return _failed_advance(ERR_INTEGRITY)

        next_generation = checkpoint["generation"] + 1
        rewritten = {
            "v": HEADER_CHECKPOINT_VERSION,
            "generation": next_generation,
            "anchor": checkpoint["anchor"],
            "tip": checkpoint["tip"],
            "finalized": target,
            "steps": checkpoint["steps"],
        }
        rewritten["hash"] = _header_checkpoint_hash(
            HEADER_CHECKPOINT_VERSION,
            next_generation,
            checkpoint["anchor"],
            checkpoint["tip"],
            target,
            checkpoint["steps"],
        )

        try:
            original = _read_bytes_or_none(path)
        except OSError:
            return _failed_advance(ERR_IO)
        try:
            _atomic_write_header_checkpoint(path, rewritten)
        except OSError:
            # Compensate: put the original bytes back best-effort.
            _restore_bytes(path, original)
            return _failed_advance(ERR_IO)
        except (TypeError, ValueError):
            # A stored value JSON cannot re-serialize is a file defect.
            return _failed_advance(ERR_STATE)

        return {
            "ok": True,
            "generation": next_generation,
            "finalized": {key: target[key] for key in HEADER_ANCHOR_KEYS},
        }


# Fixed success key order returned by :func:`apply_finalities`.
APPLY_FINALITIES_RESULT_KEYS = ("ok", "generation", "finalized", "applied")


def apply_finalities(
    path: object, documents: object, trust: object
) -> dict:
    """Apply a non-empty, ordered batch of signed finality credentials.

    :func:`apply_finalities` is the batch form of :func:`apply_finality`:
    ``documents`` must be a non-empty list and every item must carry the
    exact :func:`apply_finality` contract — top-level key order
    ``finalized, tip, auth``, nested key orders/types/S, the
    ``ledger-finality-v1`` Ed25519 envelope and ``trust.audit_signers``
    exactly as for :func:`verify_header_page`. Nothing else about
    :func:`apply_finality`, the finality credential, the HTTP endpoint or
    ``python -m ledger.cli`` changes.

    Verification is staged and all-or-nothing:

    1. **input** — ``path`` must be a non-empty string and every item's
       key order and raw types (plus the trust signers) are checked for
       the whole batch first.
    2. **state/io** — the checkpoint at ``path`` is then strictly loaded
       and fully replayed under the per-path lock shared with every other
       same-path operation (a missing file is ``io``; a parse, key-order,
       digest or replay defect is ``state``).
    3. **auth** — the items are authenticated in array order: each
       envelope's ``key_version`` must resolve in ``trust.audit_signers``
       and its Ed25519 signature must verify under the
       ``ledger-finality-v1`` domain (an unknown version or a failed
       signature is ``auth``).
    4. **integrity** — the items are applied, in order, to the replayed
       branch: each item's ``tip`` must match the same-height header's
       hash and status; its ``finalized`` target must name that tip's
       branch anchor or a confirmed header not above the tip; the
       finalized height must strictly increase from item to item and the
       tip height must never decrease. A duplicate, a regression, a
       same-height different-hash target, a pending/dropped-fork/old-fork
       target or one past the tip is rejected.

    Only when the whole batch verifies is the boundary advanced once,
    atomically, to the last item's target: the generation is incremented
    exactly once and the file rewritten in the version-3 format. When the
    last item names the boundary already stored, the call is idempotent —
    the file bytes stay exactly as they were and the generation holds,
    even when earlier items replayed history up to it. Success
    returns ``{"ok": True, "generation", "finalized", "applied"}`` in
    that key order with ``finalized`` the last item's closed boundary and
    ``applied`` the number of credentials. Failure returns only
    ``{"ok": False, "error": category}`` with category one of ``input``
    (parameters, array, key order or types), ``auth`` (an unknown version
    or a failed signature), ``integrity`` (ordering, tip, branch or
    boundary defects), ``state`` (a parse, digest or replay defect) and
    ``io`` (a missing file or a read/write error; a failed write restores
    the original bytes best-effort). Nothing is raised and a failed batch
    never changes the file bytes.
    """
    # Argument shape is validated before any file work.
    if not isinstance(path, str) or not path:
        return _failed_advance(ERR_INPUT)

    lock = _checkpoint_lock(path)
    with lock:
        # Stage 1 (input): the whole batch's exact key order and raw types,
        # and the trust signers, are settled before any file or signature
        # work — structure precedes state and trust.
        if not isinstance(documents, list) or not documents:
            return _failed_advance(ERR_INPUT)
        try:
            parsed = [_parse_finality_document(document) for document in documents]
            signers = _validate_header_trust(trust)
        except _Failure as failure:
            return _failed_advance(failure.category)
        except Exception:
            # Defensive: structurally unforeseeable inputs must report
            # rather than crash the caller.
            return _failed_advance(ERR_INPUT)

        # The persisted checkpoint is strictly loaded and fully replayed
        # before any credential is judged: a corrupt or missing file is
        # state/io regardless of the credentials it arrives with.
        try:
            loaded = _load_header_checkpoint_document(path)
        except _CheckpointError as failure:
            return _failed_advance(failure.category)
        except Exception:
            return _failed_advance(ERR_STATE)
        if loaded is None:
            # Finality can only be applied to an existing checkpoint.
            return _failed_advance(ERR_IO)
        checkpoint, _step_tips, branch = loaded

        # Stage 2 (auth): every envelope is verified in array order. A
        # later credential is never trusted because an earlier one was.
        try:
            for document, (_target, _tip, key_version, signature) in zip(
                documents, parsed
            ):
                _authenticate_finality(
                    document, key_version, signature, signers
                )
        except _Failure as failure:
            return _failed_advance(failure.category)

        # Stage 3 (integrity): walk the batch in order against the one
        # replayed branch. Inside the batch finalized heights must rise
        # strictly and tip heights may never fall; each item's tip must
        # name the branch header at that height (same hash and status) and
        # its finalized target must be that tip's branch anchor or a
        # confirmed header no higher than the tip. The stored boundary is
        # compared only once, against the last item: the batch as a whole
        # may replay history up to the boundary (idempotent) or raise it,
        # but never end below or beside it.
        finalized = checkpoint["finalized"]
        previous_target_height: int | None = None
        previous_tip_height: int | None = None
        last_target: dict | None = None
        try:
            for target, cred_tip, _version, _signature in parsed:
                # The credential's tip must be the branch header at its
                # own height — same hash and status — which rejects an old
                # fork, a dropped fork and a stale descriptor alike.
                tip_entry = branch.get(cred_tip["height"])
                if tip_entry is None or tip_entry[0] != cred_tip["tip_hash"]:
                    raise _Failure(ERR_INTEGRITY)
                if tip_entry[1] != cred_tip["status"]:
                    raise _Failure(ERR_INTEGRITY)
                # Tip heights are non-decreasing across the batch.
                if (
                    previous_tip_height is not None
                    and cred_tip["height"] < previous_tip_height
                ):
                    raise _Failure(ERR_INTEGRITY)
                previous_tip_height = cred_tip["height"]

                # Finalized heights strictly increase from item to item:
                # a duplicate or an internal regression is rejected.
                if (
                    previous_target_height is not None
                    and target["height"] <= previous_target_height
                ):
                    raise _Failure(ERR_INTEGRITY)
                previous_target_height = target["height"]

                # The target must not cross the tip the credential itself
                # describes, must name that tip's branch (the anchor or a
                # confirmed header on it — an old/dropped fork is absent),
                # and must never be pending.
                if target["height"] > cred_tip["height"]:
                    raise _Failure(ERR_INTEGRITY)
                entry = branch.get(target["height"])
                if entry is None or entry[0] != target["block_hash"]:
                    raise _Failure(ERR_INTEGRITY)
                if (
                    target != checkpoint["anchor"]
                    and entry[1] != STATUS_CONFIRMED
                ):
                    raise _Failure(ERR_INTEGRITY)

                last_target = target
        except _Failure as failure:
            return _failed_advance(failure.category)
        assert last_target is not None  # documents is shape-guaranteed non-empty

        # The batch as a whole must not move the stored boundary backwards
        # or sideways; ending exactly on it replays history and is
        # idempotent (the file bytes stay exactly as they were and the
        # generation holds), ending above it advances once.
        if last_target["height"] < finalized["height"] or (
            last_target["height"] == finalized["height"]
            and last_target["block_hash"] != finalized["block_hash"]
        ):
            return _failed_advance(ERR_INTEGRITY)
        if last_target == finalized:
            return {
                "ok": True,
                "generation": checkpoint["generation"],
                "finalized": {key: finalized[key] for key in HEADER_ANCHOR_KEYS},
                "applied": len(parsed),
            }

        next_generation = checkpoint["generation"] + 1
        rewritten = {
            "v": HEADER_CHECKPOINT_VERSION,
            "generation": next_generation,
            "anchor": checkpoint["anchor"],
            "tip": checkpoint["tip"],
            "finalized": last_target,
            "steps": checkpoint["steps"],
        }
        rewritten["hash"] = _header_checkpoint_hash(
            HEADER_CHECKPOINT_VERSION,
            next_generation,
            checkpoint["anchor"],
            checkpoint["tip"],
            last_target,
            checkpoint["steps"],
        )

        try:
            original = _read_bytes_or_none(path)
        except OSError:
            return _failed_advance(ERR_IO)
        try:
            _atomic_write_header_checkpoint(path, rewritten)
        except OSError:
            # Compensate: put the original bytes back best-effort.
            _restore_bytes(path, original)
            return _failed_advance(ERR_IO)
        except (TypeError, ValueError):
            # A stored value JSON cannot re-serialize is a file defect.
            return _failed_advance(ERR_STATE)

        return {
            "ok": True,
            "generation": next_generation,
            "finalized": {key: last_target[key] for key in HEADER_ANCHOR_KEYS},
            "applied": len(parsed),
        }


# The exact contract key order of one ``GET /v1/chain/finalities`` page.
FINALITY_PAGE_KEYS = ("anchor", "finalities", "next", "head")

# Fixed success key order returned by :func:`apply_finality_pages`.
APPLY_FINALITY_PAGES_RESULT_KEYS = (
    "ok",
    "generation",
    "finalized",
    "pages",
    "applied",
)


def _parse_finality_page(
    document: object,
) -> tuple[dict, list, dict | None, dict, tuple[dict, dict, int, str]]:
    """Stage 1 of the finality-page contract: exact key order and raw types.

    Every defect here is an input error. Returns the closed anchor, the
    parsed ``finalities`` items (each as :func:`_parse_finality_document`
    returns), the closed ``next`` anchor (or None), the raw ``head``
    credential and its parsed form.
    """
    if not isinstance(document, dict) or tuple(document.keys()) != FINALITY_PAGE_KEYS:
        raise _Failure(ERR_INPUT)
    anchor = _validate_header_anchor(document["anchor"])
    raw_items = document["finalities"]
    if not isinstance(raw_items, list):
        raise _Failure(ERR_INPUT)
    items = [_parse_finality_document(item) for item in raw_items]
    raw_next = document["next"]
    if raw_next is None:
        next_anchor = None
    else:
        next_anchor = _validate_header_anchor(raw_next)
    raw_head = document["head"]
    head = _parse_finality_document(raw_head)
    return anchor, items, next_anchor, raw_head, head


def apply_finality_pages(path: object, pages: object, trust: object) -> dict:
    """Apply a paginated ``GET /v1/chain/finalities`` history atomically.

    ``pages`` is a non-empty, ordered array of response pages, each with
    the exact top-level key order ``anchor, finalities, next, head``:
    ``anchor`` is ``{height, block_hash}``, ``finalities`` an array of
    signed ``GET /v1/chain/finality`` credentials (key order ``finalized,
    tip, auth``, the ``ledger-finality-v1`` Ed25519 envelope against
    ``trust.audit_signers`` exactly as for :func:`apply_finalities`),
    ``next`` the follow-up anchor or ``null`` and ``head`` the current
    finality credential in the same signed shape.

    Verification is staged and all-or-nothing:

def _header_page_bytes(unsigned: dict) -> bytes:
    """The signed bytes of a header page without its ``auth`` envelope:
    ``UTF8("ledger-headers-v1") || canonical_json(anchor, headers, tip)``.
    """
    return HEADER_PAGE_DOMAIN.encode("utf-8") + _canonical_json_bytes(unsigned)


def sign_header_page(
    private_key_hex: str,
    key_version: int,
    anchor: dict,
    headers: list,
    tip: dict,
) -> dict | None:
    """Build the ``{key_version, signature}`` envelope of a header page.

    The signature is an Ed25519 signature over
    ``SHA256(UTF8("ledger-headers-v1") || canonical_json({anchor, headers,
    tip}))``. Returns None when the private key is malformed.
    """
    unsigned = {"anchor": anchor, "headers": headers, "tip": tip}
    digest = hashlib.sha256(_header_page_bytes(unsigned)).digest()
    signature = crypto.sign_message(private_key_hex, digest)
    if signature is None:
        return None
    return {"key_version": key_version, "signature": signature}


def verify_header_page(
    document: object,
    anchor: object,
    tip_hash: object,
    trust: object,
) -> dict:
    """Offline-verify one signed ``GET /v1/chain/headers`` page.

    ``document`` is the decoded response with the exact top-level key order
    ``anchor, headers, tip, auth``: ``anchor`` is ``{height, block_hash}``
    (key order ``height, block_hash``), ``headers`` is an ascending list of
    ``{height, prev_hash, merkle_root, block_hash, status}`` header items,
    ``tip`` is the chain descriptor S (``tip_hash, height, length, status``)
    and ``auth`` is ``{key_version, signature}``. ``anchor`` is the
    caller-pinned anchor the page's ``anchor`` must strictly equal;
    ``tip_hash`` is the caller-pinned chain tip the page's ``tip`` must
    name. ``trust`` must carry an ``audit_signers`` list; the envelope's
    ``key_version`` selects that version's public key.

    Verification, in order: strict key order and types (``input``), signer
    lookup by ``key_version`` and the Ed25519 signature over
    ``SHA256(UTF8("ledger-headers-v1") || canonical_json(document without
    auth))`` (unknown version/key or a signature that does not verify is
    ``auth``), the pinned anchor, the recomputed header hashes and prev_hash
    links (heights consecutive from the anchor, pending only at the page
    tail), and the tip descriptor (``integrity``). An empty page is valid
    only when its anchor is the pinned tip; a page ending before the tip is
    a valid non-final pagination page. Never raises for malformed input.

    Returns ``{"ok": True, "anchor", "tip", "verified_block_hashes"}`` on
    success (the hashes in ascending page order, empty for an anchor=tip
    page) or ``{"ok": False, "error": "input"|"auth"|"integrity"}``.
    """
    try:
        closed_anchor, closed_tip, verified_hashes = _verify_header_page(
            document, anchor, tip_hash, trust
        )
    except _Failure as failure:
        return {"ok": False, "error": failure.category}
    except Exception:
        # Defensive: structurally unforeseeable inputs must report rather than
        # crash the verifying process.
        return {"ok": False, "error": ERR_INPUT}
    return {
        "ok": True,
        "anchor": closed_anchor,
        "tip": closed_tip,
        "verified_block_hashes": verified_hashes,
    }


def _validate_header_anchor(raw: object) -> dict:
    """Structural validation of a closed ``{height, block_hash}`` anchor."""
    if not isinstance(raw, dict) or tuple(raw.keys()) != HEADER_ANCHOR_KEYS:
        raise _Failure(ERR_INPUT)
    if not _is_int(raw["height"]) or raw["height"] < 0:
        raise _Failure(ERR_INPUT)
    if not crypto.is_hex64(raw["block_hash"]):
        raise _Failure(ERR_INPUT)
    return {"height": raw["height"], "block_hash": raw["block_hash"]}


def _validate_header_trust(trust: object) -> dict:
    """Parse ``trust.audit_signers`` into ``{version: public_key}``.

    The list must be non-empty; every entry must carry a positive,
    non-boolean integer ``version`` and a 64-lowercase-hex ``public_key``.
    Versions must be unique. Any other defect is an input error.
    """
    if not isinstance(trust, dict):
        raise _Failure(ERR_INPUT)
    raw_signers = trust.get("audit_signers")
    if not isinstance(raw_signers, list) or not raw_signers:
        raise _Failure(ERR_INPUT)
    signers: dict[int, str] = {}
    for entry in raw_signers:
        if not isinstance(entry, dict):
            raise _Failure(ERR_INPUT)
        version = entry.get("version")
        public_key = entry.get("public_key")
        if not _is_int(version) or version < 1:
            raise _Failure(ERR_INPUT)
        if not crypto.is_hex64(public_key):
            raise _Failure(ERR_INPUT)
        if version in signers:
            raise _Failure(ERR_INPUT)
        signers[version] = public_key
    return signers


def _parse_header_page(document: object) -> tuple[dict, list[dict], dict, int, str]:
    """Stage 1 of the header-page contract: exact key order and raw types.

    Every defect here is an input error. Returns the closed anchor, the
    closed header items, the closed tip descriptor, the envelope's key
    version and its signature.
    """
    if not isinstance(document, dict):
        raise _Failure(ERR_INPUT)
    if tuple(document.keys()) != HEADER_PAGE_KEYS:
        raise _Failure(ERR_INPUT)
    page_anchor = _validate_header_anchor(document["anchor"])
    raw_headers = document["headers"]
    if not isinstance(raw_headers, list):
        raise _Failure(ERR_INPUT)
    headers: list[dict] = []
    for item in raw_headers:
        if not isinstance(item, dict) or tuple(item.keys()) != HEADER_ITEM_KEYS:
            raise _Failure(ERR_INPUT)
        if not _is_int(item["height"]) or item["height"] < 0:
            raise _Failure(ERR_INPUT)
        if (
            not crypto.is_hex64(item["prev_hash"])
            or not crypto.is_hex64(item["merkle_root"])
            or not crypto.is_hex64(item["block_hash"])
        ):
            raise _Failure(ERR_INPUT)
        if item["status"] not in (STATUS_PENDING, STATUS_CONFIRMED):
            raise _Failure(ERR_INPUT)
        headers.append({key: item[key] for key in HEADER_ITEM_KEYS})
    raw_tip = document["tip"]
    if not isinstance(raw_tip, dict) or tuple(raw_tip.keys()) != HEADER_TIP_KEYS:
        raise _Failure(ERR_INPUT)
