@staticmethod
def _block_descriptor(block: Block) -> dict:
    """The chain descriptor S of the prefix ending at ``block``."""
    return {
        "tip_hash": block.block_hash,
        "height": block.height,
        # The length counts every block including the genesis block.
        "length": block.height + 1,
        "status": block.status,
